exercise.solution:
const promotions = {
  none: () => 0,
  percent10: (total) => total * 0.1,
  flat100: (total) => (total >= 1000 ? 100 : 0),
};

function discount(type, total) {
  const strategy = Object.hasOwn(promotions, type) ? promotions[type] : null;
  if (!strategy) throw new Error(`unknown promotion: ${type}`);
  return strategy(total);
}
